function opponentHTML(player,slot){const active=currentPlayer(state).id===player.id,stopped=eventBanner?.kind==='stop'&&eventBanner.targetId===player.id,count=Math.min(10,player.hand.length),backs=Array.from({length:count},(_,i)=>`<i style="--offset:${i-(count-1)/2}"><span>${sigilHTML()}</span></i>`).join(''),winning=session.phase!=='round'&&session.results.at(-1)?.winnerId===player.id;return `<div class="opponent seat-${slot} ${active?'active':''} ${stopped?'sealed':''} ${propRattled.has(player.id)?'rattled':''} ${winning?'winner-seat':''} ${player.hand.length===1?'last-card':''}" data-player-id="${player.id}" role="group" aria-label="${active?`התור עכשיו אצל ${player.name}`:`${player.name}, יד נסתרת`}"><div class="seat-marker"><i class="house-pin ${player.house||''}"></i><span>${player.name}</span><small>${archetypeName[player.archetype]||'יריב'}</small><b><i></i><bdi>${player.hand.length}</bdi></b></div><div class="opponent-fan">${backs}</div>${propsHTML(player)}${stopped?'<span class="stop-seal" aria-hidden="true"><svg viewBox="0 0 64 64"><path d="M24 49 12 30c-3-6 4-9 8-4l5 6V15c0-6 8-6 8 0v15-18c0-6 8-6 8 0v18-13c0-6 8-6 8 0v16-7c0-6 8-6 8 0v12c0 12-8 20-20 20-8 0-13-3-17-9z"/></svg></span>':''}${quip?.player===player.id?`<div class="speech" role="status">${quip.text}</div>`:''}</div>`;}
function opponentSeats(players){const layouts={1:['top'],2:['left','right'],3:['left','top','right'],4:['far-left','left','right','far-right'],5:['far-left','left','top','right','far-right']};return players.map((p,i)=>opponentHTML(p,(layouts[players.length]||layouts[5])[i]||'top')).join('');}
function statusHTML(){const bits=[];if(state.activePenalty)bits.push(`<span class="penalty-token" aria-label="משיכת ${state.activePenalty.amount} קלפים"><bdi>+${state.activePenalty.amount}</bdi><i></i></span>`);if(state.taki?.open){const human=state.taki.ownerId==='p0'&&currentPlayer(state).id==='p0',owner=state.players.find(p=>p.id===state.taki.ownerId)?.name,color=colorName[state.taki.color]||'';bits.push(`<div class="taki-panel ${human?'yours':'bot-taki'}" style="--taki-color:${colorHex[state.taki.color]}" role="status"><div><b>TAKI פתוח · ${color}</b><small>${human?`אפשר להניח עוד קלפים בצבע ${color}`:`${owner} ממשיך לשחק`}</small></div>${human?'<button class="close-taki" data-close-taki>סיימתי — לסגור TAKI</button>':''}</div>`);}if(state.freePlay)bits.push('<span class="extra-turn-token" aria-label="תור נוסף">+</span>');return bits.join('');}
function choiceHTML(){if(state.awaitingColor?.playerId!=='p0')return'';return `<div class="color-choice" role="dialog" aria-label="בחירת צבע"><div class="gem-ring"><span>בחרו צבע</span>${COLORS.map(c=>`<button class="gem ${c}" data-color="${c}" aria-label="${colorName[c]}"><i></i></button>`).join('')}</div></div>`;}
function eventHTML(){if(!eventBanner)return'';const player=state.players.find(p=>p.id===eventBanner.playerId),name=eventBanner.playerId==='p0'?'אתם':player?.name||'',card=eventBanner.cardId?state.discardPile.find(c=>c.id===eventBanner.cardId):null;const labels={play:'הניח קלף',draw:'משך קלף',penalty:`משך ${eventBanner.amount||''} קלפים`,stop:'דילג על תור',reverse:'שינה כיוון',plus:'קיבל מהלך נוסף',plus2:`העלה את העונש ל־${eventBanner.amount||2}+`,color:`בחר ${colorName[state.activeColor]||'צבע'}`,king:'הניח מלך',takiOpen:'פתח TAKI',takiClose:'סגר TAKI',takiCycle:'סגר ופתח TAKI חדש'};const visual=card?cardHTML(card,{activeColor:state.activeColor}):`<span class="spot-card-back">${sigilHTML()}</span>`;return `<div class="action-spotlight ${eventBanner.kind}" role="status" aria-live="assertive"><div class="spot-visual">${visual}</div><div class="spot-copy"><strong>${name}</strong><b>${labels[eventBanner.kind]||captionLine}</b>${eventBanner.kind==='takiOpen'?`<small>TAKI ${colorName[state.taki?.color]||''} פתוח — ממשיכים להניח קלפים</small>`:''}</div></div>`;}
function flightsHTML(){return drawFlights.map(f=>Array.from({length:f.count},(_,i)=>`<span class="card-flight to-${f.slot}" data-flight-id="${f.id}" style="--flight-delay:${i*(f.count>5?42:72)}ms;--flight-index:${i}" aria-hidden="true"></span>`).join('')).join('');}
function roundMarkerHTML(){if(session.mode!=='tavern')return'<div class="round-marker">משחק מהיר</div>';return `<div class="round-marker">${session.suddenDeath?'יד מכרעת':`סיבוב <bdi>${session.round}</bdi> מתוך <bdi>${session.totalRounds}</bdi>`}</div>`;}
function gameHTML(){
  const human=state.players[0],active=currentPlayer(state),isHumanTurn=session.phase==='round'&&active.id===human.id&&!state.awaitingColor,legal=new Set(isHumanTurn?getLegalCards(state,human.id).map(c=>c.id):[]),shown=human.hand.slice(0,13),more=human.hand.length-shown.length,top=topCard(state);
  const turnHint=hint||(isHumanTurn?'התור שלך':`התור של ${active.name}`);
  const under=state.discardPile.slice(-4,-1),fresh=top.id!==lastRenderedTopId;lastRenderedTopId=top.id;
  const arrows='<svg class="direction-arrows" viewBox="0 0 300 300" aria-label="כיוון המשחק"><path d="M57 181A105 105 0 0 1 226 74"/><path d="m219 54 9 22-24 4"/><path d="M243 119A105 105 0 0 1 74 226"/><path d="m81 246-9-22 24-4"/></svg>';
  const handCards=shown.map((card,i)=>{const incoming=incomingCardDelays.get(card.id);return cardHTML(card,{legal:isHumanTurn&&legal.has(card.id),highlight:settings.playableHints,selected:selected===card.id,incoming:!!incoming,arrivalDelay:incoming?incoming.delay-(performance.now()-incoming.started):0,index:i,total:shown.length});}).join('');
  return `<main class="app-shell table-shell ${settings.reducedMotion?'reduced-motion':''}" dir="rtl" style="--active:${colorHex[state.activeColor]||'#b78b45'}"><div class="ambient-scene" aria-hidden="true"><i class="fire-glow"></i><i class="candle-glow"></i><i class="room-haze"></i></div><section class="game ${isHumanTurn?'human-turn':'waiting'}"><header class="game-head"><button class="rune-menu" data-open="pause" aria-label="תפריט והשהיה"><i></i><i></i><i></i></button>${roundMarkerHTML()}${scoreBoardHTML()}</header><div class="board"><div class="direction-engraving ${state.direction<0?'counter':''} ${eventBanner?.kind==='reverse'?'lit':''} ${state.taki?.open?'taki-lit':''}">${arrows}${sigilHTML('table-sigil')}<span class="house-node red ${state.activeColor==='red'?'on':''}"></span><span class="house-node blue ${state.activeColor==='blue'?'on':''}"></span><span class="house-node green ${state.activeColor==='green'?'on':''}"></span><span class="house-node yellow ${state.activeColor==='yellow'?'on':''}"></span></div><div class="opponents">${opponentSeats(state.players.slice(1,6))}</div><div class="center"><div class="status-stack">${statusHTML()}</div><button class="pile draw-pile" data-draw aria-label="משיכת קלף. ${state.drawPile.length} קלפים נותרו" style="--deck-depth:${Math.min(8,Math.ceil(state.drawPile.length/15))}px"><span class="back-sigil">${sigilHTML()}</span><span class="deck-count"><bdi>${state.drawPile.length}</bdi></span></button><div class="pile discard ${fresh?'fresh':''}" style="--pile-turn:${((state.discardPile.length%7)-3)*.7}deg" aria-label="הקלף המוביל. הצבע הפעיל: ${colorName[state.activeColor]||'חופשי'}"><div class="discard-under">${under.map((card,i)=>`<span class="under under-${i}">${cardHTML(card)}</span>`).join('')}</div>${cardHTML(top,{activeColor:state.activeColor})}<span class="active-stone ${state.activeColor||'wild'}"></span></div>${eventHTML()}</div>${flightsHTML()}<span class="sr-only" aria-live="polite" aria-atomic="true">${screenReaderLine}</span></div><footer class="hand-area ${isHumanTurn?'your-active':''}"><div class="turn-whisper"><span>${turnHint}</span></div><div class="hand ${state.taki?.open?'taki-active':''}">${handCards}</div>${more>0&&isHumanTurn?`<button class="reveal-hand" data-show-all>חשיפת כל הקלפים <bdi>(${human.hand.length})</bdi></button>`:''}${quip?.player==='p0'?`<div class="human-quip">${quip.text}</div>`:''}</footer></section>${choiceHTML()}${showAllCards?allCardsHTML(human,legal,top):''}${summaryHTML()}${sheetHTML()}</main>`;
}
function allCardsHTML(human,legal,top){return `<div class="all-cards" role="dialog" aria-label="כל הקלפים ביד"><header><button data-hide-all aria-label="סגירה">×</button><div><small>הקלף שעל השולחן</small>${cardHTML(top,{activeColor:state.activeColor})}</div><h2>כל הקלפים שלך</h2></header><div class="all-cards-grid">${human.hand.map(card=>cardHTML(card,{legal:legal.has(card.id),highlight:settings.playableHints})).join('')}</div></div>`;}
function summaryHTML(){
  if(!session||session.phase==='round'||(!roundResultVisible&&session.phase!=='round'))return'';
  if(session.mode==='quick'){const winner=state.players.find(p=>p.id===session.championId);return `<div class="result-wrap"><article class="tally-board"><small>סוף הסיבוב</small><h2>${winnerLine(winner)}</h2><div class="result-actions"><button class="leather-button primary" data-quick>לסיבוב נוסף</button><button class="text-link" data-home>לצאת מהשולחן</button></div></article></div>`;}
  if(session.phase==='matchFinished'){const champion=session.roster.find(p=>p.id===session.championId);return `<div class="result-wrap"><article class="tally-board champion">${sigilHTML('result-sigil')}<small>אלוף הפונדק</small><h2>${champion?.id==='p0'?'אתם':champion?.name}</h2><div class="final-standing">${standings(session).map((p,i)=>`<div><b><bdi>${i+1}</bdi></b><span>${p.name}</span><strong><bdi>${p.score}</bdi></strong></div>`).join('')}</div><div class="result-actions"><button class="leather-button primary" data-tavern>ערב נוסף</button><button class="text-link" data-home>לעזוב את השולחן</button></div></article></div>`;}
  const result=session.results.at(-1),winner=session.roster.find(p=>p.id===result.winnerId),losers=session.roster.filter(p=>p.id!==result.winnerId),equation=losers.map(p=>result.remaining[p.id]).join(' + ');
  return `<div class="result-wrap table-result"><article class="tally-board round-tally"><small>${session.suddenDeath?'יד מכרעת':`סיבוב <bdi>${result.round}</bdi>`}</small><h2>${winnerLine(winner)}</h2><div class="round-count">${losers.map((p,i)=>`<span style="--token-order:${i}"><small>${p.name}</small><b><bdi>${result.remaining[p.id]}</bdi></b></span>`).join('')}</div><div class="coin-total"><span dir="ltr">${equation}</span><strong><bdi>+${result.points}</bdi></strong></div><div class="result-actions"><button class="leather-button primary" data-next>${session.suddenDeath?'ליד המכרעת':'לסיבוב הבא'}</button><button class="text-link" data-home>לשמור ולצאת</button></div></article></div>`;
}
function sheetHTML(){
  if(!sheet)return'';
  if(sheet==='quick')return `<div class="sheet-wrap"><article class="tavern-sheet"><h2>משחק מהיר</h2><p>יד אחת, בלי ניקוד מצטבר.</p><label>מספר שחקנים</label><div class="segmented">${[2,3,4,6,8,10].map(n=>`<button data-players="${n}" class="${settings.playerCount===n?'on':''}">${n}</button>`).join('')}</div><button class="parchment-button primary" data-quick>להתחיל</button><button class="text-link" data-close-sheet>חזרה</button></article></div>`;
  if(sheet==='rules')return `<div class="sheet-wrap"><article class="tavern-sheet rules"><h2>חוקי Elder Taki</h2><p>התאימו צבע, מספר או סמל. אם משכתם קלף, הוא יחכה לתור הבא. הראשון שמרוקן את היד מנצח.</p><h3>TAKI</h3><p>TAKI פותח רצף בצבע אחד. אפשר להמשיך לשחק או ללחוץ על <b>סגירת TAKI</b>. רק הפקודה האחרונה ברצף פועלת; אחרי פלוס חייבים לשחק שוב.</p><h3>מלך וסופר TAKI</h3><p><b>מלך</b> מבטל כל מגבלה, אבל לעולם לא מסיים תור — חייבים להניח אחריו קלף נוסף. אם מלך נשאר על הערימה, השחקן הבא רשאי להניח כל קלף. סופר TAKI אחרי מלך מאפשר לבחור את צבע הרצף.</p><h3>משחק פונדק</h3><p>חמישה סיבובים מול שלושה יריבים. המנצח בכל יד מקבל נקודה על כל קלף שנותר בידי האחרים. שוויון אחרי הסיבוב החמישי מוביל ליד מכרעת.</p><h3>הקלפים העתיקים</h3><p><b>עצור</b> מדלג, <b>שנה כיוון</b> הופך את הסדר, <b>פלוס</b> מעניק מהלך נוסף, <b>2+</b> מצטבר ו<b>שנה צבע</b> בוחר בית.</p><button class="parchment-button" data-close-sheet>הבנתי</button></article></div>`;
  return `<div class="sheet-wrap"><article class="tavern-sheet"><h2>${sheet==='pause'?'המשחק מושהה':'הגדרות'}</h2>${toggleRow('צלילי משחק','sound')}${toggleRow('אווירת פונדק','ambience')}${toggleRow('דברי יריבים','dialogue')}${toggleRow('כתוביות לאירועי משחק','captions')}${toggleRow('הדגשת קלפים שאפשר לשחק','playableHints')}${toggleRow('רטט','haptics')}${toggleRow('צמצום תנועה','reducedMotion')}<button class="parchment-button" data-close-sheet>${sheet==='pause'?'לחזור לשולחן':'סיום'}</button>${sheet==='pause'?'<button class="text-link" data-home>שמירה ויציאה</button>':''}</article></div>`;
}
function toggleRow(label,key){return `<div class="toggle-row"><label>${label}</label><button class="iron-switch ${settings[key]?'on':''}" data-toggle="${key}" aria-pressed="${settings[key]}"><i></i></button></div>`;}

function render(){root.innerHTML=view==='home'?homeHTML():gameHTML();bind();}
function goHome(){clearTimeout(botTimer);clearTimeout(takiTimer);clearTimeout(eventTimer);clearTimeout(roundEndTimer);ambience.stop();view='home';sheet=null;render();}
function bind(){
  root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{sheet=b.dataset.open;render();});
  root.querySelectorAll('[data-close-sheet]').forEach(b=>b.onclick=()=>{sheet=null;render();});
  root.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{settings[b.dataset.toggle]=!settings[b.dataset.toggle];saveSettings(settings);if(b.dataset.toggle==='ambience'||b.dataset.toggle==='sound'){ambience.stop();ambience.start(settings);}render();});
  root.querySelectorAll('[data-players]').forEach(b=>b.onclick=()=>{settings.playerCount=+b.dataset.players;saveSettings(settings);render();});
  root.querySelector('[data-tavern]')?.addEventListener('click',()=>{clearMatch();startSession('tavern');});
  root.querySelector('[data-quick]')?.addEventListener('click',()=>{clearMatch();startSession('quick');});
  root.querySelector('[data-resume]')?.addEventListener('click',()=>startSession('tavern',loadMatch()));
  root.querySelector('[data-next]')?.addEventListener('click',()=>{feedback('shuffle',settings);setSession(startNextRound(session));render();scheduleGame();});
  root.querySelectorAll('[data-home]').forEach(b=>b.onclick=goHome);
  root.querySelector('[data-draw]')?.addEventListener('click',()=>{if(currentPlayer(state).id==='p0'&&!state.taki?.open)submit({type:ACTIONS.DRAW,playerId:'p0'});});
  root.querySelector('[data-close-taki]')?.addEventListener('click',()=>submit({type:ACTIONS.END_TURN,playerId:'p0'}));
  root.querySelector('[data-show-all]')?.addEventListener('click',()=>{showAllCards=true;render();});
  root.querySelector('[data-hide-all]')?.addEventListener('click',()=>{showAllCards=false;render();});
  root.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>submit({type:ACTIONS.CHOOSE_COLOR,playerId:'p0',color:b.dataset.color}));
  root.querySelectorAll('.hand .card.legal,.all-cards-grid .card.legal').forEach(card=>{let startY=0,moved=false;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});}};card.onpointerdown=e=>{startY=e.clientY;moved=false;card.setPointerCapture(e.pointerId);selected=card.dataset.cardId;card.classList.add('selected');};card.onpointermove=e=>{if(!card.hasPointerCapture(e.pointerId))return;const dy=e.clientY-startY;if(Math.abs(dy)>7)moved=true;if(!showAllCards)card.style.transform=`translateY(${Math.min(0,dy)}px) rotate(0deg)`;};card.onpointerup=e=>{const dy=e.clientY-startY;card.releasePointerCapture(e.pointerId);if(showAllCards||dy<-58||!moved)submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});else render();};});
}

if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;try{void Promise.resolve(context.registerTool({name:'read_game_state',title:'Read Elder Taki game',description:'Read the current Elder Taki match status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return session?{mode:session.mode,phase:session.phase,round:session.round,totalRounds:session.totalRounds,suddenDeath:session.suddenDeath,scores:session.scores,currentPlayer:currentPlayer(state).name,activeColor:state.activeColor,humanCardCount:state.players[0].hand.length,opponents:state.players.slice(1).map(p=>({name:p.name,cardCount:p.hand.length}))}:{phase:'home'};}})).catch(()=>{});}catch{}}
registerWebMCP();render();
